-- County-by-year jail rates by race -- how much more often Black residents are jailed than white ones.
-- Auto-generated by scripts/gen_evidence_pages.py: 128,507 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
-- grouped on year-like text/number column YEAR (NOT date-cast -- avoids the 8-digit epoch trap); LIMIT bounds it.
select "YEAR" as year, count(*) as records
from THE_LIBRARY.JUSTICE.JAIL_RACIAL_DISPARITY_BY_COUNTY
group by 1
order by 1
limit 1000
